import {
  Mjml,
  MjmlBody,
  MjmlButton,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  MjmlWrapper,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type CardsTimeline_CardsTimelineVariant =
  | "default"
  | "with-badge"
  | "with-accent"
  | "image-top"
  | "image-bottom";

interface CardsTimeline_CardsTimelineProps {
  theme?: EmailTheme;
  variant?: CardsTimeline_CardsTimelineVariant;
  date?: string;
  badge?: string;
  title?: string;
  description?: string;
  imageSrc?: string;
  imageAlt?: string;
}

const CardsTimeline_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const CardsTimeline_CardsTimelineSection = (
  props: Omit<CardsTimeline_CardsTimelineProps, "theme">
) => {
  const { badge, date, description, imageAlt, imageSrc, title, variant } = {
    badge: "Today",
    date: "Monday",
    description: "Description of event",
    imageAlt: "One workspace. Every team.",
    imageSrc: emailAsset("timelines/cards.jpg"),
    title: "Miles traveled",
    variant: "default",
    ...props,
  };
  const dark =
    variant === "with-accent" ||
    variant === "image-top" ||
    variant === "image-bottom";
  let cardBackgroundColor = "#fffffe";
  if (dark) {
    cardBackgroundColor = "#030712";
  } else if (variant === "with-badge") {
    cardBackgroundColor = "#f9fafb";
  }
  const image = (
    <MjmlImage
      alt={imageAlt}
      borderRadius="4px"
      padding="0"
      src={imageSrc}
      width="536px"
    />
  );
  return (
    <MjmlSection backgroundColor="#fffffe" padding="16px">
      <MjmlColumn
        backgroundColor={cardBackgroundColor}
        borderRadius={variant === "default" ? "0" : "8px"}
        padding="16px"
      >
        {variant === "image-top" ? (
          <>
            {image}
            <MjmlSpacer height="16px" />
          </>
        ) : null}
        {(() => {
          if (variant === "default") {
            return null;
          }
          return (
            <MjmlButton
              align="left"
              backgroundColor={dark ? "#312e81" : "#eef2ff"}
              borderRadius="9999px"
              color={dark ? "#c7d2fe" : "#4f46e5"}
              fontFamily={CardsTimeline_fontFamily}
              fontSize="12px"
              fontWeight="600"
              innerPadding="3px 8px"
              padding="0"
            >
              {badge}
            </MjmlButton>
          );
        })()}
        <MjmlText
          color={dark ? "#9ca3af" : "#6b7280"}
          fontFamily={CardsTimeline_fontFamily}
          fontSize="13px"
          lineHeight="18px"
          padding={variant === "default" ? "0" : "12px 0 0"}
        >
          {date}
        </MjmlText>
        <MjmlText
          color={dark ? "#fffffe" : "#030712"}
          fontFamily={CardsTimeline_fontFamily}
          fontSize="20px"
          fontWeight="600"
          lineHeight="28px"
          padding="8px 0 0"
        >
          {variant === "with-accent" ? `✓ ${title}` : title}
        </MjmlText>
        <MjmlText
          color={dark ? "#d1d5db" : "#4b5563"}
          fontFamily={CardsTimeline_fontFamily}
          fontSize="16px"
          lineHeight="24px"
          padding="8px 0 0"
        >
          {description}
        </MjmlText>
        {variant === "image-bottom" ? (
          <>
            <MjmlSpacer height="16px" />
            {image}
          </>
        ) : null}
      </MjmlColumn>
    </MjmlSection>
  );
};

const CardsTimeline_CardsTimeline = ({
  theme = defaultTheme,
  ...props
}: CardsTimeline_CardsTimelineProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Miles traveled</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <CardsTimeline_CardsTimelineSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

CardsTimeline_CardsTimeline.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies CardsTimeline_CardsTimelineProps;

const __CardsTimeline = CardsTimeline_CardsTimeline;

type Changelog_ChangelogVariant =
  | "muted-left"
  | "muted-right"
  | "basic-left"
  | "basic-right"
  | "accent-left"
  | "accent-right";

type Changelog_ChangelogLayout = "line" | "boxed";

interface Changelog_ChangelogProps {
  theme?: EmailTheme;
  variant?: Changelog_ChangelogVariant;
  layout?: Changelog_ChangelogLayout;
  version?: string;
  date?: string;
  category?: string;
  title?: string;
  description?: string;
}

const Changelog_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const Changelog_resolveChangelogAlignment = (right: boolean) =>
  right
    ? ({ content: "right", meta: "left" } as const)
    : ({ content: "left", meta: "right" } as const);

const Changelog_ChangelogSection = (
  props: Omit<Changelog_ChangelogProps, "theme">
) => {
  const { category, date, description, layout, title, variant, version } = {
    category: "Refactoring",
    date: "19 Jan",
    description:
      "Introduced a new timeline pattern to clearly represent ordered states and progression, improving clarity across step-based and time-based flows.",
    layout: "line",
    title: "Refined layouts",
    variant: "muted-left",
    version: "v1.0.9",
    ...props,
  };
  const right = variant.endsWith("-right");
  const muted = variant.startsWith("muted");
  const accent = variant.startsWith("accent");
  const alignment = Changelog_resolveChangelogAlignment(right);
  const borderColor = accent ? "#4f46e5" : "#d1d5db";
  let contentPadding = right ? "0 24px 0 0" : "0 0 0 24px";
  let titleColor = "#030712";
  if (layout === "boxed") {
    contentPadding = "24px";
  }
  if (accent) {
    titleColor = "#4f46e5";
  } else if (muted) {
    titleColor = "#6b7280";
  }
  const meta = (
    <MjmlColumn
      padding={right ? "0 0 0 16px" : "0 16px 0 0"}
      verticalAlign="top"
      width="28%"
    >
      <MjmlButton
        align={alignment.meta}
        backgroundColor={muted ? "#f9fafb" : "#eef2ff"}
        border={`1px solid ${muted ? "#d1d5db" : "#a5b4fc"}`}
        borderRadius="9999px"
        color={muted ? "#4b5563" : "#4f46e5"}
        fontFamily={Changelog_fontFamily}
        fontSize="12px"
        fontWeight="500"
        innerPadding="2px 8px"
        padding="0"
      >
        {version}
      </MjmlButton>
      <MjmlText
        align={alignment.meta}
        color="#030712"
        fontFamily={Changelog_fontFamily}
        fontSize="16px"
        fontWeight="600"
        lineHeight="24px"
        padding="8px 0 0"
      >
        {date}
      </MjmlText>
      <MjmlText
        align={alignment.meta}
        color="#9ca3af"
        fontFamily={Changelog_fontFamily}
        fontSize="12px"
        lineHeight="16px"
        padding="0"
      >
        {category}
      </MjmlText>
    </MjmlColumn>
  );
  const content = (
    <MjmlColumn
      backgroundColor={layout === "boxed" ? "#f9fafb" : undefined}
      borderLeft={right ? undefined : `2px solid ${borderColor}`}
      borderRadius={layout === "boxed" ? "8px" : "0"}
      borderRight={right ? `2px solid ${borderColor}` : undefined}
      padding={contentPadding}
      verticalAlign="top"
      width="72%"
    >
      <MjmlText
        align={alignment.content}
        color={titleColor}
        fontFamily={Changelog_fontFamily}
        fontSize="20px"
        fontWeight="600"
        lineHeight="28px"
        padding="0"
      >
        {title}
      </MjmlText>
      <MjmlText
        align={alignment.content}
        color="#4b5563"
        fontFamily={Changelog_fontFamily}
        fontSize="16px"
        lineHeight="24px"
        padding="12px 0 0"
      >
        {description}
      </MjmlText>
    </MjmlColumn>
  );
  return (
    <MjmlSection backgroundColor="#fffffe" padding="24px">
      {right ? content : meta}
      {right ? meta : content}
    </MjmlSection>
  );
};

const Changelog_Changelog = ({
  theme = defaultTheme,
  ...props
}: Changelog_ChangelogProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Refined layouts</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <Changelog_ChangelogSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

Changelog_Changelog.PreviewProps = {
  layout: "line",
  theme: defaultTheme,
  variant: "muted-left",
} satisfies Changelog_ChangelogProps;

const __Changelog = Changelog_Changelog;

type SplitTimeline_SplitCardsVariant =
  | "muted"
  | "muted-reverse"
  | "boxed"
  | "boxed-reverse"
  | "accent"
  | "accent-reverse"
  | "image-top"
  | "image-top-reverse"
  | "image-bottom"
  | "image-bottom-reverse";

interface SplitTimeline_SplitCardsProps {
  theme?: EmailTheme;
  variant?: SplitTimeline_SplitCardsVariant;
  index?: string;
  label?: string;
  date?: string;
  badge?: string;
  title?: string;
  description?: string;
  imageSrc?: string;
  imageAlt?: string;
}

const SplitTimeline_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const SplitTimeline_SplitCardsSection = (
  props: Omit<SplitTimeline_SplitCardsProps, "theme">
) => {
  const {
    badge,
    date,
    description,
    imageAlt,
    imageSrc,
    index,
    label,
    title,
    variant,
  } = {
    badge: "Today",
    date: "Monday",
    description: "Description of event",
    imageAlt: "Placeholder image",
    imageSrc: emailAsset("timelines/cards.jpg"),
    index: "01",
    label: "Miles traveled",
    title: "Miles traveled",
    variant: "muted",
    ...props,
  };
  const reverse = variant.endsWith("-reverse");
  const accent = variant.startsWith("accent");
  const imageTop = variant.startsWith("image-top");
  const imageBottom = variant.startsWith("image-bottom");
  const dark = accent || imageTop || imageBottom;
  let cardBackgroundColor = "#fffffe";
  if (dark) {
    cardBackgroundColor = "#030712";
  } else if (variant.startsWith("boxed")) {
    cardBackgroundColor = "#f9fafb";
  }
  const meta = (
    <MjmlColumn
      padding={reverse ? "16px 0 16px 16px" : "16px 16px 16px 0"}
      verticalAlign="top"
      width="24%"
    >
      <MjmlText
        align={reverse ? "left" : "right"}
        color="#030712"
        fontFamily={SplitTimeline_fontFamily}
        fontSize="60px"
        fontWeight="600"
        lineHeight="64px"
        padding="0"
      >
        {index}
      </MjmlText>
      <MjmlText
        align={reverse ? "left" : "right"}
        color="#9ca3af"
        fontFamily={SplitTimeline_fontFamily}
        fontSize="12px"
        fontWeight="600"
        lineHeight="16px"
        padding="0"
      >
        {label}
      </MjmlText>
    </MjmlColumn>
  );
  const image = (
    <MjmlImage
      alt={imageAlt}
      borderRadius="4px"
      padding="0"
      src={imageSrc}
      width="392px"
    />
  );
  const card = (
    <MjmlColumn
      backgroundColor={cardBackgroundColor}
      borderRadius={variant.startsWith("muted") ? "0" : "8px"}
      padding="16px"
      verticalAlign="top"
      width="76%"
    >
      {imageTop ? (
        <>
          {image}
          <MjmlSpacer height="16px" />
        </>
      ) : null}
      <MjmlButton
        align="left"
        backgroundColor={dark ? "#312e81" : "#eef2ff"}
        borderRadius="9999px"
        color={dark ? "#c7d2fe" : "#4f46e5"}
        fontFamily={SplitTimeline_fontFamily}
        fontSize="12px"
        fontWeight="600"
        innerPadding="3px 8px"
        padding="0"
      >
        {badge}
      </MjmlButton>
      <MjmlText
        color={dark ? "#9ca3af" : "#6b7280"}
        fontFamily={SplitTimeline_fontFamily}
        fontSize="13px"
        lineHeight="18px"
        padding="8px 0 0"
      >
        {date}
      </MjmlText>
      <MjmlText
        color={dark ? "#fffffe" : "#030712"}
        fontFamily={SplitTimeline_fontFamily}
        fontSize="20px"
        fontWeight="600"
        lineHeight="28px"
        padding="8px 0 0"
      >
        {title}
      </MjmlText>
      <MjmlText
        color={dark ? "#d1d5db" : "#4b5563"}
        fontFamily={SplitTimeline_fontFamily}
        fontSize="16px"
        lineHeight="24px"
        padding="4px 0 0"
      >
        {description}
      </MjmlText>
      {imageBottom ? (
        <>
          <MjmlSpacer height="16px" />
          {image}
        </>
      ) : null}
    </MjmlColumn>
  );
  return (
    <MjmlSection backgroundColor="#fffffe" padding="16px 24px">
      {reverse ? card : meta}
      {reverse ? meta : card}
    </MjmlSection>
  );
};

const SplitTimeline_SplitCards = ({
  theme = defaultTheme,
  ...props
}: SplitTimeline_SplitCardsProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Miles traveled</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <SplitTimeline_SplitCardsSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

SplitTimeline_SplitCards.PreviewProps = {
  theme: defaultTheme,
  variant: "muted",
} satisfies SplitTimeline_SplitCardsProps;

const __SplitTimeline = SplitTimeline_SplitCards;

type StackedTimeline_StackedTimelineVariant =
  | "muted-left"
  | "muted-right"
  | "basic-left"
  | "basic-right"
  | "completed-left"
  | "completed-right"
  | "accent-left"
  | "accent-right";

type StackedTimeline_StackedTimelineLayout = "line" | "boxed";

interface StackedTimeline_StackedTimelineProps {
  theme?: EmailTheme;
  variant?: StackedTimeline_StackedTimelineVariant;
  layout?: StackedTimeline_StackedTimelineLayout;
  index?: string;
  label?: string;
  title?: string;
  description?: string;
}

const StackedTimeline_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const StackedTimeline_resolveStackedTimelineStyles = ({
  accent,
  boxed,
  muted,
  right,
}: {
  accent: boolean;
  boxed: boolean;
  muted: boolean;
  right: boolean;
}) => {
  const borderColor = accent ? "#4f46e5" : "#d1d5db";
  let backgroundColor: string | undefined;
  let contentPadding = right ? "0 24px 0 0" : "0 0 0 24px";
  let titleColor = "#030712";
  if (boxed) {
    backgroundColor = accent ? "#030712" : "#f9fafb";
    contentPadding = "24px";
  }
  if (boxed && accent) {
    titleColor = "#fffffe";
  } else if (accent) {
    titleColor = "#4f46e5";
  } else if (muted) {
    titleColor = "#6b7280";
  }
  return {
    backgroundColor,
    borderLeft: right ? undefined : `2px solid ${borderColor}`,
    borderRight: right ? `2px solid ${borderColor}` : undefined,
    contentAlign: right ? "right" : "left",
    contentPadding,
    descriptionColor: boxed && accent ? "#d1d5db" : "#4b5563",
    metaAlign: right ? "left" : "right",
    metaPadding: right ? "0 0 0 16px" : "0 16px 0 0",
    titleColor,
  } as const;
};

const StackedTimeline_StackedTimelineSection = (
  props: Omit<StackedTimeline_StackedTimelineProps, "theme">
) => {
  const { description, index, label, layout, title, variant } = {
    description:
      "Every mile tells a story. Each step forward adds to the journey, shaping the path ahead and marking progress along the way.",
    layout: "line",
    title: "Total distance",
    variant: "muted-left",
    ...props,
  };
  const boxed = layout === "boxed";
  const right = variant.endsWith("-right");
  const muted = variant.startsWith("muted");
  const accent =
    variant.startsWith("completed") || variant.startsWith("accent");
  const resolvedIndex = index ?? (boxed ? "A" : "01");
  const resolvedLabel = label ?? (boxed ? "Cargo number" : "Miles traveled");
  const styles = StackedTimeline_resolveStackedTimelineStyles({
    accent,
    boxed,
    muted,
    right,
  });
  const meta = (
    <MjmlColumn padding={styles.metaPadding} verticalAlign="top" width="28%">
      <MjmlText
        align={styles.metaAlign}
        color={muted ? "#9ca3af" : "#030712"}
        fontFamily={StackedTimeline_fontFamily}
        fontSize="60px"
        fontWeight="600"
        lineHeight="64px"
        padding="0"
      >
        {resolvedIndex}
      </MjmlText>
      <MjmlText
        align={styles.metaAlign}
        color="#9ca3af"
        fontFamily={StackedTimeline_fontFamily}
        fontSize="12px"
        fontWeight="600"
        lineHeight="16px"
        padding="0"
      >
        {resolvedLabel}
      </MjmlText>
    </MjmlColumn>
  );
  const content = (
    <MjmlColumn
      backgroundColor={styles.backgroundColor}
      borderLeft={styles.borderLeft}
      borderRadius={boxed ? "8px" : "0"}
      borderRight={styles.borderRight}
      padding={styles.contentPadding}
      verticalAlign="top"
      width="72%"
    >
      <MjmlText
        align={styles.contentAlign}
        color={styles.titleColor}
        fontFamily={StackedTimeline_fontFamily}
        fontSize="20px"
        fontWeight="600"
        lineHeight="28px"
        padding="0"
      >
        {variant.startsWith("completed") ? `✓ ${title}` : title}
      </MjmlText>
      <MjmlText
        align={styles.contentAlign}
        color={styles.descriptionColor}
        fontFamily={StackedTimeline_fontFamily}
        fontSize="16px"
        lineHeight="24px"
        padding="12px 0 0"
      >
        {description}
      </MjmlText>
    </MjmlColumn>
  );
  return (
    <MjmlSection backgroundColor="#fffffe" padding="24px">
      {right ? content : meta}
      {right ? meta : content}
    </MjmlSection>
  );
};

const StackedTimeline_StackedTimeline = ({
  theme = defaultTheme,
  ...props
}: StackedTimeline_StackedTimelineProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Total distance</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <StackedTimeline_StackedTimelineSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

StackedTimeline_StackedTimeline.PreviewProps = {
  layout: "line",
  theme: defaultTheme,
  variant: "muted-left",
} satisfies StackedTimeline_StackedTimelineProps;

const __StackedTimeline = StackedTimeline_StackedTimeline;

export interface TimelineItem {
  index?: string;
  label?: string;
  date?: string;
  version?: string;
  category?: string;
  badge?: string;
  title: string;
  description?: string;
  image?: {
    src: string;
    alt?: string;
  };
  completed?: boolean;
}

export interface TimelineProps {
  theme?: Parameters<typeof __Changelog>[0]["theme"];
  items?: TimelineItem[];
  layout?: "line" | "boxed" | "cards" | "split";
  alignment?: "left" | "right";
  appearance?: "muted" | "basic" | "accent";
  reverse?: boolean;
  variant?:
    | Parameters<typeof __CardsTimeline>[0]["variant"]
    | Parameters<typeof __Changelog>[0]["variant"]
    | Parameters<typeof __SplitTimeline>[0]["variant"]
    | Parameters<typeof __StackedTimeline>[0]["variant"];
}

const timelineVariant = ({
  alignment,
  appearance,
}: Required<Pick<TimelineProps, "alignment" | "appearance">>) =>
  `${appearance}-${alignment}` as const;

const timelineItemValues = (item: TimelineItem | undefined) => {
  const {
    badge,
    category,
    date,
    description,
    image,
    index,
    label,
    title,
    version,
  } = item ?? {};
  return {
    badge,
    category,
    date,
    description,
    imageAlt: image?.alt,
    imageSrc: image?.src,
    index,
    label,
    title,
    version,
  };
};

export const Timeline = ({
  theme,
  items,
  layout = "line",
  alignment = "left",
  appearance = "basic",
  reverse = false,
  variant: variantOverride,
}: TimelineProps) => {
  const [item] = items ?? [];
  const props = { ...timelineItemValues(item), theme };
  if (layout === "cards") {
    const variant = (() => {
      if (item?.image) {
        if (reverse) {
          return "image-bottom";
        }
        return "image-top";
      }
      if (item?.badge) {
        return "with-badge";
      }
      if (appearance === "accent") {
        return "with-accent";
      }
      return "default";
    })();
    return (
      <__CardsTimeline
        {...props}
        variant={
          (variantOverride ?? variant) as Parameters<
            typeof __CardsTimeline
          >[0]["variant"]
        }
      />
    );
  }
  if (layout === "split") {
    const base = (() => {
      if (item?.image) {
        return "image-top";
      }
      if (appearance === "basic") {
        return "boxed";
      }
      return appearance;
    })();
    const variant = variantOverride ?? `${base}${reverse ? "-reverse" : ""}`;
    return (
      <__SplitTimeline
        {...props}
        variant={variant as Parameters<typeof __SplitTimeline>[0]["variant"]}
      />
    );
  }
  if (item?.version || item?.category) {
    return (
      <__Changelog
        {...props}
        layout={layout}
        variant={
          (variantOverride ??
            timelineVariant({ alignment, appearance })) as Parameters<
            typeof __Changelog
          >[0]["variant"]
        }
      />
    );
  }
  const variant = item?.completed
    ? `completed-${alignment}`
    : timelineVariant({ alignment, appearance });
  return (
    <__StackedTimeline
      {...props}
      layout={layout}
      variant={
        (variantOverride ?? variant) as Parameters<
          typeof __StackedTimeline
        >[0]["variant"]
      }
    />
  );
};

Timeline.PreviewProps = {
  alignment: "left",
  appearance: "basic",
  layout: "line",
  reverse: false,
} satisfies TimelineProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
